mapper.select:
SELECT 


    a.deleted = 0

        AND (a.name LIKE CONCAT('%', #{q.keyword}, '%')
          OR a.alias LIKE CONCAT('%', #{q.keyword}, '%')
          OR a.artifact_no LIKE CONCAT('%', #{q.keyword}, '%')
          OR a.description LIKE CONCAT('%', #{q.keyword}, '%'))


        AND (a.category_id = #{q.categoryId}
          OR a.category_id IN (SELECT id FROM artifact_category WHERE parent_id = #{q.categoryId} AND deleted = 0))

    AND a.pit_id = #{q.pitId}
    AND a.material_id = #{q.materialId}
    AND a.period_id = #{q.periodId}
    AND a.hall_id = #{q.hallId}
    AND a.is_treasure = #{q.isTreasure}
    AND a.status = #{q.status}


    ORDER BY a.view_count DESC, a.id ASC
    ORDER BY a.created_at DESC, a.id DESC
    ORDER BY a.is_treasure DESC, a.id ASC
